=Here is the LinkedIn data of the prospect:

- First Name: {{ $json.first_name }}
- Last Name: {{ $json.last_name }}
- Current Role: {{ $json.current_role }}
- Current Company: {{ $json.current_company }}
- Tenure at Company: {{ $json.tenure_at_company }}
- Location: {{ $json.location }}
- Headline: {{ $json.headline }}
- About: {{ $json.about }}
- Previous Company: {{ $json.previous_company_1 }}
- Previous Role: {{ $json.previous_role_1 }}
- Education: {{ $json.education_degree }} at {{ $json.education_school }}
- Top Skills: {{ $json.top_skills }}
- Volunteering: {{ $json.volunteering_role }}

CONTEXT (do not mention this directly — use it only to understand what pain to hint at):
The prospect likely deals with scattered data across departments, making decision-making slow and reactive. They probably feel the pressure of not having a single clear picture of business performance in real time.

Generate the prospect description and icebreaker now.

parameters.jsCode:
const items = $input.all();

function tryFixAndParse(str) {
  if (!str) return null;

  // Sometimes LLM forgets closing brace → try to repair
  let cleaned = str.trim();

  // If missing last "}", add it
  if (!cleaned.endsWith("}")) {
    cleaned += "}";
  }

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}

return items.map(item => {
  const raw = item.json.output;

  const parsed = tryFixAndParse(raw);

  return {
    json: {
      description: parsed?.description ?? "PARSE_FAILED",
      icebreaker: parsed?.icebreaker ?? "PARSE_FAILED",
      raw: raw
    }
  };
});

